4.1 Two estimators of proportions
When estimating a binomial proportion \(p\) from \(n\) independent trials, the standard maximum likelihood estimator is the sample mean, \(\hat{p}_1 = \bar{X}\). However, this estimator can have high variance for small sample sizes, particularly when the true \(p\) is close to 0 or 1.
An alternative is a smoothed estimator (often called an “add-one-in” or Laplace estimator), defined as \(\hat{p}_2 = \frac{\sum X_i + 1}{n + 2}\). This estimator introduces a slight bias but aims to reduce overall variance.
To compare them, we use Monte Carlo simulation to estimate their Mean Squared Error (MSE) across a grid of true \(p\) values ranging from 0 to 1. The MSE is calculated as \(E[(\hat{p} - p)^2]\). We also compute the standard error of our Monte Carlo estimates to plot 95% confidence bands, allowing us to see exactly where the bias-variance tradeoff makes \(\hat{p}_2\) a superior choice for small sample sizes \(n\).
Code
## Estimating Functios
p_est1 &lt;- function(x) mean(x)

p_est2 &lt;- function(x) {
    n &lt;- length (x)
    (sum(x) + 1) / (n+2)
}

## Functions for estimating MSE
mse_est_mc &lt;- function(n,p,no_sim,p_est)
{
    sq_error &lt;- rep(0, no_sim)
    for(i_sim in 1:no_sim)
    {  sq_error[i_sim] &lt;- (p_est( rbinom(n,1,p) ) - p)^2
    }
    list(mse=mean(sq_error), sd = sqrt(var(sq_error)/no_sim) )
}


mse_p1 &lt;- function(n,p,no_sim)
{
    sq_error &lt;- rep(0, no_sim)
    for(i_sim in 1:no_sim)
    {  sq_error[i_sim] &lt;- (p1_est( rbinom(n,1,p) ) - p)^2
    }
    list(mse=mean(sq_error), sd = sqrt(var(sq_error)/no_sim) )
}

mse_p2 &lt;- function(n,p,no_sim)
{
    sq_error &lt;- rep(0, no_sim)
    for(i_sim in 1:no_sim)
    {  sq_error[i_sim] &lt;- (p2_est( rbinom(n,1,p) ) - p)^2
    }
    list(mse=mean(sq_error), sd = sqrt(var(sq_error)/no_sim) )
}

## Simulation
par( mfrow=c(2,2), mar=c(4,4,2,1) )

no_sim &lt;- 10000

p_set &lt;- seq(0,1,by = 0.05)

risk_est1 &lt;- risk_est2 &lt;- rep(0, length(p_set))
sd_risk_est1 &lt;- sd_risk_est2 &lt;- rep(0, length(p_set))


n_set &lt;- c(2,10,50,100)

for( n in n_set )
{

    for(i in 1:length(p_set) )
    {
        output_est &lt;- mse_est_mc(n=n,p=p_set[i],no_sim=no_sim,p_est1)
        risk_est1[i] &lt;- output_est$mse
        sd_risk_est1[i] &lt;- output_est$sd

        output_est &lt;- mse_est_mc(n=n,p=p_set[i],no_sim=no_sim,p_est2)
        risk_est2[i] &lt;- output_est$mse
        sd_risk_est2[i] &lt;- output_est$sd

    }

    plot(p_set, risk_est1,type="l", 
         xlab="p",ylab="MSE",main=paste("n=",n))
    points(p_set, risk_est1 + 1.96*sd_risk_est1,type="l",lty=2)
    points(p_set, risk_est1 - 1.96*sd_risk_est1,type="l",lty=2)

    points(p_set, risk_est2,type="l",col=2)
    points(p_set, risk_est2 + 1.96*sd_risk_est2,type="l",lty=2,col=2)
    points(p_set, risk_est2 - 1.96*sd_risk_est2,type="l",lty=2,col=2)

}

13.1 A function for simulating Markov chain


Code
## a function that similates a markov chain
sim_one_mc &lt;- function (ini, iters, n = 10)
{
    forward &lt;- function(i) 
    {  if( i == n - 1) 0 
       else i + 1
    }
    backward &lt;- function(i)
    {  if( i == 0 ) n - 1
       else i - 1
    }

    mc &lt;- rep (0, iters + 1)
    mc[1] &lt;- ini
    for (i in 2: (iters+1))
    {

        u &lt;- runif(1)
        if(u &lt; 0.45)  mc[i] &lt;- forward(mc[i-1])
        else if( u &gt; 0.55 ) mc[i] &lt;- backward(mc[i-1])
        else mc[i] &lt;- mc[i-1]

    }
    mc
}
